send_email.beforeRequest:
const has = (v) => v != null && v !== '';
const b = request.body;
request.body = {personalizations: JSON.parse(inputs.to).map((x) => ({to: [{email: String(x).trim()}]})), from: b.from, reply_to: {email: has(inputs.reply_to) ? inputs.reply_to : inputs.from}, subject: b.subject, content: [{type: inputs.content_type == 'text' ? 'text/plain' : 'text/html', value: inputs.content}]};
return request;

send_dynamic_template.beforeRequest:
const has = (v) => v != null && v !== '';
const b = request.body, data = JSON.parse(inputs.template_data);
request.body = {personalizations: JSON.parse(inputs.to).map((x) => ({to: [{email: String(x).trim()}], dynamic_template_data: data})), from: b.from, reply_to: {email: has(inputs.reply_to) ? inputs.reply_to : inputs.from}, template_id: b.template_id};
return request;

create_or_update_contact.beforeRequest:
const has = (v) => v != null && v !== '';
const ids = has(inputs.list_ids) ? JSON.parse(inputs.list_ids) : [];
const contact = {...(has(inputs.custom_fields) ? JSON.parse(inputs.custom_fields) : {}), email: inputs.email};
if (has(inputs.first_name)) contact.first_name = inputs.first_name;
if (has(inputs.last_name)) contact.last_name = inputs.last_name;
request.body = {...(ids && ids.length > 0 && {list_ids: ids}), contacts: [contact]};
return request;

find_list_by_name.afterResponse:
const lists = [...((response && response.result) || [])];
let next = response && response._metadata && response._metadata.next;
while (next) {
  const page = call({method: 'GET', url: next});
  lists.push(...(page.result || []));
  next = page._metadata && page._metadata.next;
}
const target = inputs.name.trim().toLowerCase();
const matches = lists.filter((list) => list.name.trim().toLowerCase() === target);
return {found: matches.length > 0, lists: matches};
